import { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import UploadForm from '../components/UploadForm';

const Gallery = () => {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const { user, logout } = useAuth();

  useEffect(() => {
    fetchImages();
  }, []);

  // ✅ Fetch images from the server
  const fetchImages = async () => {
    if (!user?.token) {
      console.warn('⚠️ No token found, skipping fetch');
      setLoading(false);
      return;
    }

    console.log('🔹 Fetching images...');
    setLoading(true);

    try {
      const { data } = await axios.get('/api/gallery', {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      setImages(data);
      console.log(`✅ Images fetched: ${data.length}`);
    } catch (error) {
      console.error('❌ Error fetching images:', error);

      if (error.response?.status === 401) {
        alert('Session expired. Please log in again.');
        logout(); // ✅ Clear token and user data
      } else {
        alert(error.response?.data?.message || 'Error fetching images');
      }
      setImages([]);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Like an image
  const handleLike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/like`, {}, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      fetchImages(); // ✅ Refresh after like
    } catch (error) {
      alert(error.response?.data?.message || 'Error liking image');
    }
  };

  // ✅ Unlike an image
  const handleUnlike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/unlike`, {}, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      fetchImages(); // ✅ Refresh after unlike
    } catch (error) {
      alert(error.response?.data?.message || 'Error unliking image');
    }
  };

  return (
    <div className="container my-4 py-4">
      {/* ✅ Only Admin Can See Upload Option */}
      {user?.role === 'admin' && (
        <div className="mb-4">
          <UploadForm onUploadSuccess={fetchImages} />
        </div>
      )}

      {/* ✅ Loading Indicator */}
      {loading && <p className="text-center">Loading images...</p>}

      {/* ✅ Handle Empty State */}
      {!loading && images.length === 0 && (
        <p className="text-center text-muted">No images available.</p>
      )}

      {/* ✅ Display Images */}
      <div className="row">
        {images.map((image) => (
          <div key={image._id} className="col-lg-4 col-md-6 col-sm-12 mb-4 d-flex align-items-stretch">
            <div className="card shadow border-0">
              <img 
                src={image.imageUrl} 
                alt="Gallery" 
                className="card-img-top img-fluid" 
                style={{ objectFit: 'cover', height: '250px' }}
              />
              <div className="card-body d-flex flex-column">
                <p className="card-text mb-1">
                  Uploaded by: <strong>{image.uploadedBy?.name || 'Unknown'}</strong>
                </p>
                <p className="mb-2">{image.likes.length} likes</p>
                {image.likes.includes(user._id) ? (
                  <button 
                    onClick={() => handleUnlike(image._id)} 
                    className="btn btn-danger mt-auto"
                  >
                    ❤️ Unlike
                  </button>
                ) : (
                  <button 
                    onClick={() => handleLike(image._id)} 
                    className="btn btn-primary mt-auto"
                  >
                    👍 Like
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gallery;
